#!/usr/bin/env bash
# Generates the types of every contract for each component:
#   TypeScript -> media-server/src/contracts/   (quicktype, plus the schemas for runtime validation)
#   Dart       -> apps/shared/lib/src/contracts/ (quicktype, then dart format)
#   Python     -> backend/app/contracts/         (datamodel-codegen)
# Generated files are committed; CI regenerates them and fails on any difference.
set -euo pipefail

CONTRACTS="$(cd "$(dirname "$0")/.." && pwd)"
ROOT="$(dirname "$CONTRACTS")"
PYTHON="${PYTHON:-$ROOT/backend/.venv/bin/python}"
cd "$CONTRACTS"

# Schema paths contain no spaces, so plain word splitting is safe (and works in the bash 3 of macOS).
# shellcheck disable=SC2207
MODELS=($(node --input-type=module -e 'import { modelFiles } from "./scripts/schemas.mjs"; console.log(modelFiles().join("\n"))'))
QUICKTYPE=(npx --no-install quicktype --src-lang schema --no-combine-classes --quiet)
HEADER="// Generated by contracts/scripts/codegen.sh from contracts/*.json. Do not edit."

# Puts HEADER and a blank line on top of a file (portable: no sed -i).
add_header() {
  { printf '%s\n\n' "$HEADER"; cat "$1"; } > "$1.tmp"
  mv "$1.tmp" "$1"
}

# TypeScript
TS_OUT="$ROOT/media-server/src/contracts"
mkdir -p "$TS_OUT"
"${QUICKTYPE[@]}" --lang typescript --acronym-style original --just-types --prefer-const-values --no-date-times --no-uuids -o "$TS_OUT/types.ts" "${MODELS[@]}"
add_header "$TS_OUT/types.ts"
node scripts/typescript-extras.mjs "$TS_OUT"

# Dart
DART_OUT="$ROOT/apps/shared/lib/src/contracts"
mkdir -p "$DART_OUT"
"${QUICKTYPE[@]}" --lang dart --no-uuids -o "$DART_OUT/contracts.dart" "${MODELS[@]}"
add_header "$DART_OUT/contracts.dart"
DART_TEST="$ROOT/apps/shared/test"
node scripts/dart-extras.mjs "$DART_OUT" "$DART_TEST"
dart format --output=write "$DART_OUT/contracts.dart" "$DART_OUT/messages.dart" "$DART_TEST/contract_models.dart" > /dev/null

# Python: datamodel-codegen reads a directory, so give it the schemas without examples and node_modules.
STAGE="$(mktemp -d)"
trap 'rm -rf "$STAGE"' EXIT
cp common.json "$STAGE/"
for model in "${MODELS[@]}"; do
  mkdir -p "$STAGE/$(dirname "$model")"
  cp "$model" "$STAGE/$model"
done
PY_OUT="$ROOT/backend/app/contracts"
rm -rf "$PY_OUT"
"$PYTHON" -m datamodel_code_generator \
  --input "$STAGE" --input-file-type jsonschema --output "$PY_OUT" \
  --output-model-type pydantic_v2.BaseModel --target-python-version 3.12 \
  --use-standard-collections --use-union-operator --use-title-as-name --collapse-root-models \
  --use-schema-description --use-field-description --field-constraints \
  --capitalise-enum-members --enum-field-as-literal one --disable-timestamp \
  --custom-file-header "# Generated by contracts/scripts/codegen.sh from contracts/*.json. Do not edit." \
  --formatters ruff-format

echo "codegen: done"
